var B32_ALPHABETS={
  rfc4648:  'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567',
  base32hex:'0123456789ABCDEFGHIJKLMNOPQRSTUV',
  crockford:'0123456789ABCDEFGHJKMNPQRSTVWXYZ',
  zbase32:  'ybndrfg8ejkmcpqxot1uwisza345h769'
};
var B32_PAD={ rfc4648:true, base32hex:true, crockford:false, zbase32:false };
function b32ToUtf8(str){
  var out=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<0x80) out.push(c);
    else if(c<0x800) out.push(0xC0|(c>>6),0x80|(c&63));
    else if(c>=0xD800&&c<=0xDBFF&&i+1<str.length){
      var c2=str.charCodeAt(i+1);
      if(c2>=0xDC00&&c2<=0xDFFF){
        var cp=0x10000+((c-0xD800)<<10)+(c2-0xDC00); i++;
        out.push(0xF0|(cp>>18),0x80|((cp>>12)&63),0x80|((cp>>6)&63),0x80|(cp&63));
      } else out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63));
    }
    else out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63));
  }
  return out;
}
function b32FromUtf8(bytes){
  var s='', i=0;
  while(i<bytes.length){
    var b=bytes[i];
    if(b<0x80){ s+=String.fromCharCode(b); i++; }
    else if(b>=0xC0&&b<0xE0){ s+=String.fromCharCode(((b&31)<<6)|(bytes[i+1]&63)); i+=2; }
    else if(b>=0xE0&&b<0xF0){ s+=String.fromCharCode(((b&15)<<12)|((bytes[i+1]&63)<<6)|(bytes[i+2]&63)); i+=3; }
    else {
      var cp=((b&7)<<18)|((bytes[i+1]&63)<<12)|((bytes[i+2]&63)<<6)|(bytes[i+3]&63); i+=4;
      cp-=0x10000; s+=String.fromCharCode(0xD800+(cp>>10),0xDC00+(cp&1023));
    }
  }
  return s;
}
function b32Encode(bytes, variant){
  var alpha=B32_ALPHABETS[variant];
  if(!alpha) return { value:null, error:'未知变体: '+variant };
  var out='', bits=0, acc=0;
  for(var i=0;i<bytes.length;i++){
    acc=(acc<<8)|bytes[i]; bits+=8;
    while(bits>=5){ bits-=5; out+=alpha[(acc>>bits)&31]; }
  }
  if(bits>0) out+=alpha[(acc<<(5-bits))&31];
  if(B32_PAD[variant]){ while(out.length%8!==0) out+='='; }
  return { value:out, error:null };
}
function b32Normalize(str, variant){
  var s=String(str).replace(/[\s-]/g,'');
  if(variant==='crockford'){
    s=s.toUpperCase().replace(/[IL]/g,'1').replace(/O/g,'0');
  } else if(variant==='rfc4648'||variant==='base32hex'){
    s=s.toUpperCase();
  } else if(variant==='zbase32'){
    s=s.toLowerCase();
  }
  return s.replace(/=+$/,'');
}
function b32Decode(str, variant){
  var alpha=B32_ALPHABETS[variant];
  if(!alpha) return { value:null, error:'未知变体: '+variant };
  var s=b32Normalize(str, variant);
  var out=[], bits=0, acc=0;
  for(var i=0;i<s.length;i++){
    var v=alpha.indexOf(s[i]);
    if(v<0) return { value:null, error:'非法字符: '+s[i] };
    acc=(acc<<5)|v; bits+=5;
    if(bits>=8){ bits-=8; out.push((acc>>bits)&255); }
  }
  return { value:out, error:null };
}
function b32EncodeStr(str, variant){ return b32Encode(b32ToUtf8(String(str)), variant); }
function b32DecodeStr(str, variant){
  var r=b32Decode(str, variant);
  if(r.error) return r;
  return { value:b32FromUtf8(r.value), error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { B32_ALPHABETS:B32_ALPHABETS, b32ToUtf8:b32ToUtf8, b32FromUtf8:b32FromUtf8,
    b32Encode:b32Encode, b32Decode:b32Decode, b32Normalize:b32Normalize,
    b32EncodeStr:b32EncodeStr, b32DecodeStr:b32DecodeStr };
}
if (typeof window !== 'undefined') {
  window.Base32ForgePure = { B32_ALPHABETS:B32_ALPHABETS, b32ToUtf8:b32ToUtf8, b32FromUtf8:b32FromUtf8,
    b32Encode:b32Encode, b32Decode:b32Decode, b32Normalize:b32Normalize,
    b32EncodeStr:b32EncodeStr, b32DecodeStr:b32DecodeStr };
}
